<?php
namespace Azula\SmsStudio;

/** Additive SMS-owned storage only. No foreign tables, destructive DDL or authority on install. */
final class M6Schema
{
    public static function columns():array
    {
        return [
            'campaign_meta'=>"id bigint unsigned NOT NULL AUTO_INCREMENT,\ncampaign_id bigint unsigned NOT NULL,\npublic_id char(32) NOT NULL,\npurpose varchar(24) NOT NULL DEFAULT 'campaign',\ntrashed_at bigint NOT NULL DEFAULT 0,\nupdated_at bigint NOT NULL,\nPRIMARY KEY  (id),\nUNIQUE KEY campaign_meta (campaign_id),\nUNIQUE KEY campaign_public (public_id),\nKEY purpose_trash (purpose,trashed_at)",
            'sendplans'=>"id bigint unsigned NOT NULL AUTO_INCREMENT,\ncampaign_id bigint unsigned NOT NULL,\naudience_id bigint unsigned NOT NULL,\nrevision bigint unsigned NOT NULL,\nstate varchar(32) NOT NULL,\nmode varchar(12) NOT NULL,\nenvironment tinyint unsigned NOT NULL,\nauto_test tinyint unsigned NOT NULL DEFAULT 0,\nreleased_at bigint NOT NULL DEFAULT 0,\nactor_id bigint unsigned NOT NULL,\nprovider_revision bigint unsigned NOT NULL,\nrecipient_count bigint unsigned NOT NULL,\nselected_recipient_id bigint unsigned NOT NULL DEFAULT 0,\nqueue_cursor bigint unsigned NOT NULL DEFAULT 0,\nretry_count bigint unsigned NOT NULL DEFAULT 0,\napproval_hash char(64) NOT NULL,\nbinding_hash char(64) NOT NULL,\npayload longtext NOT NULL,\napproved_at bigint NOT NULL,\nexpires_at bigint NOT NULL,\nstart_at bigint NOT NULL,\nnext_check bigint NOT NULL DEFAULT 0,\nupdated_at bigint NOT NULL,\nPRIMARY KEY  (id),\nUNIQUE KEY plan_approval (approval_hash),\nKEY campaign_plan (campaign_id,id),\nKEY plan_due (state,next_check)",
            'send_items'=>"id bigint unsigned NOT NULL AUTO_INCREMENT,\ncampaign_id bigint unsigned NOT NULL,\nplan_id bigint unsigned NOT NULL,\nrecipient_id bigint unsigned NOT NULL,\nphone_hash char(64) NOT NULL,\nstate varchar(32) NOT NULL,\nattempt_id bigint unsigned DEFAULT NULL,\nPRIMARY KEY  (id),\nUNIQUE KEY dispatch_campaign_phone (campaign_id,phone_hash),\nKEY plan_cursor (plan_id,state,id)",
            'links'=>"id bigint unsigned NOT NULL AUTO_INCREMENT,\ncampaign_id bigint unsigned NOT NULL,\npublic_token char(32) NOT NULL,\ndestination longtext NOT NULL,\ndestination_hash char(64) NOT NULL,\ncreated_at bigint NOT NULL,\nPRIMARY KEY  (id),\nUNIQUE KEY link_token (public_token),\nUNIQUE KEY campaign_destination (campaign_id,destination_hash)",
            'clicks'=>"id bigint unsigned NOT NULL AUTO_INCREMENT,\ncampaign_id bigint unsigned NOT NULL,\nlink_id bigint unsigned NOT NULL,\nvisitor_hash char(64) NOT NULL,\nreceipt_token char(32) NOT NULL,\nclicked_at bigint NOT NULL,\nobserved_at bigint NOT NULL DEFAULT 0,\nstage_session_hash char(64) DEFAULT NULL,\nPRIMARY KEY  (id),\nUNIQUE KEY click_receipt (receipt_token),\nKEY campaign_click (campaign_id,clicked_at),\nKEY visitor_campaign (visitor_hash,campaign_id),\nKEY stage_session (stage_session_hash,clicked_at)",
            'journey'=>"id bigint unsigned NOT NULL AUTO_INCREMENT,\ncampaign_id bigint unsigned NOT NULL,\nclick_id bigint unsigned NOT NULL,\nvisitor_hash char(64) NOT NULL,\nkind varchar(32) NOT NULL,\nevent_key char(64) NOT NULL,\noccurred_at bigint NOT NULL,\nPRIMARY KEY  (id),\nUNIQUE KEY journey_event (event_key),\nKEY campaign_event (campaign_id,occurred_at),\nKEY kind_event (kind,occurred_at)",
            'conversions'=>"id bigint unsigned NOT NULL AUTO_INCREMENT,\norder_id bigint unsigned NOT NULL,\ncampaign_id bigint unsigned NOT NULL,\nclick_id bigint unsigned NOT NULL,\nstage_session_hash char(64) NOT NULL,\norder_created bigint NOT NULL,\nassociated_at bigint NOT NULL,\nverified_at bigint NOT NULL,\nstatus varchar(32) NOT NULL,\ncurrency varchar(8) NOT NULL,\nrevenue_minor bigint NOT NULL DEFAULT 0,\npurchase_eligible tinyint unsigned NOT NULL DEFAULT 0,\nreason varchar(64) NOT NULL,\nPRIMARY KEY  (id),\nUNIQUE KEY attributed_order (order_id),\nKEY campaign_order (campaign_id,order_created),\nKEY conversion_verify (verified_at,id)",
        ];
    }
}
